insert into public.menu_items (category_id, name_en, name_ar, name_ku, ing_en, ing_ar, ing_ku, price, photo_url, tags, is_available) values ('salads', 'Golden Chicken Salad', 'سلطة الدجاج الذهبية', 'سەڵاتەی مریشکی زێڕین', 'Lollo rosso, Iceberg, sweet corn, red beans, chicken, golden mustard, Parmesan shards.', 'لولو روسو، آيسبرغ، ذرة حلوة، فاصوليا حمراء، دجاج، خردل ذهبي، شرائح بارميزان.', 'لۆلۆ رۆسۆ، کاهووی ئایسبێرگ، گەنمەشامی شیرین، فاسۆلیای سوور، مریشک، خەردەلی زێڕین، و دنکی پارمیسان.', 12500, 'https://r2.mynu.site/images/67c05717d8908969203b54ba/items/hd/500886135.jpeg', '{}', true);
insert into public.menu_items (category_id, name_en, name_ar, name_ku, ing_en, ing_ar, ing_ku, price, photo_url, tags, is_available) values ('salads', 'Tomato & Pomegranate Salad', 'سلطة الطماطم والرمان', 'Tomato & Pomegranate Salad', 'Fresh tomatoes, hot green peppers, crunchy walnuts, and juicy pomegranate, tossed with zesty pomegranate dressing, olive oil, and a hint of lemon — sweet, spicy, and refreshing! ', 'طماطم طازجة، فلفل أخضر حار، جوز مقرمش، ورمان طري، ممزوجة بصلصة رمان منعشة، وزيت الزيتون، ولمسة من الليمون — مزيج حلو وحار ومنعش! 🍅🌶️✨', null, 7000, 'https://r2.mynu.site/images/67c05717d8908969203b54ba/items/hd/248189434.jpeg', '{}', true);
insert into public.menu_items (category_id, name_en, name_ar, name_ku, ing_en, ing_ar, ing_ku, price, photo_url, tags, is_available) values ('salads', 'Chicken Ceasar Salad', 'سلطة سيزر بالدجاج ', 'Chicken Ceasar Salad', 'Arabic lettuce, cherry tomatoes, lolo leaves, croutons, tender chicken, Parmesan, and a touch of dried orange, all tossed in creamy Caesar dressing — a refreshing twist on a classic! ', 'خس عربي، طماطم كرزية، أوراق لولو، مكعبات خبز محمّصة، دجاج طري، جبنة بارميزان، ولمسة من البرتقال المجفف، جميعها ممزوجة بصلصة سيزر الكريمية — لمسة منعشة على طبق كلاسيكي! 🥗✨', null, 10000, 'https://r2.mynu.site/images/67c05717d8908969203b54ba/items/hd/1846138.jpeg', '{}', true);
insert into public.menu_items (category_id, name_en, name_ar, name_ku, ing_en, ing_ar, ing_ku, price, photo_url, tags, is_available) values ('salads', 'Avocado Citrus Delight ', 'متعة الأفوكادو بالحمضيات', 'Avocado Citrus Delight ', 'A playful mix of crisp iceberg tossed in zesty lemon pesto, topped with tangy feta, a sprinkle of green zaatar, avocado, juicy mango & pomegranate bursts. ', 'مزيج مرح من خس الآيسبرغ المقرمش، ممزوج ببيستو الليمون المنعش، ومزيّن بجبنة فيتا اللاذعة، ورشة من الزعتر الأخضر، وأفوكادو، ومانجو، وحبات رمان متفجرة بالنكهة. 🥑🥭✨', null, 10000, 'https://r2.mynu.site/images/67c05717d8908969203b54ba/items/hd/144459470.jpeg', '{}', true);
insert into public.menu_items (category_id, name_en, name_ar, name_ku, ing_en, ing_ar, ing_ku, price, photo_url, tags, is_available) values ('salads', 'Rocca Bloom Salad', 'سلطة روكا بلوم', 'سەڵاتەی رووکا بلۆم', 'Fresh rocca leaves tossed with grilled halloumi, segments of crisp apple, toasted walnuts, and a delicate balsamic sauce', 'أوراق جرجير الطازجة ممزوجة مع جبنة الحلوم المشوية، وشرائح التفاح، والجوز المحمص، وصوص بالساميك الرقيق.', 'گەڵای جەرجیری تازە تێکەڵ بە پەنیری حەلومی برژاو و پارچەی سێو و گوێزی برژاو و سۆسێکی بەلسەمیک.', 7000, 'https://r2.mynu.site/images/67c05717d8908969203b54ba/items/hd/111294773.jpeg', '{}', true);
insert into public.menu_items (category_id, name_en, name_ar, name_ku, ing_en, ing_ar, ing_ku, price, photo_url, tags, is_available) values ('soups', 'Shiitake Mushroom Soup', 'شوربة فطر الشيتاكي', 'شۆربای قارچکی شیتاکی', null, null, null, 6000, 'https://r2.mynu.site/images/67c05717d8908969203b54ba/items/hd/417331777.jpeg', '{}', true);
insert into public.menu_items (category_id, name_en, name_ar, name_ku, ing_en, ing_ar, ing_ku, price, photo_url, tags, is_available) values ('fries', 'Cesar Fries', 'Cesar Fries', 'Cesar Fries', 'Our signature fries take a trip to the coast. Drenched in rich Caesar cream and finished with a sharp Parmesan crumble for a snack that’s bold and free-spirited.', 'Our signature fries take a trip to the coast. Drenched in rich Caesar cream and finished with a sharp Parmesan crumble for a snack that’s bold and free-spirited.', 'Our signature fries take a trip to the coast. Drenched in rich Caesar cream and finished with a sharp Parmesan crumble for a snack that’s bold and free-spirited.', 8000, 'https://r2.mynu.site/images/67c05717d8908969203b54ba/items/hd/195293015.jpeg', '{}', true);
