insert into public.menu_items (category_id, name_en, name_ar, name_ku, ing_en, ing_ar, ing_ku, price, photo_url, tags, is_available) values ('fries', 'Sweet Chili Popcorn Chicken', 'دجاج بوب كورن بالفلفل الحلو الحار', 'مریشکی گەنمەشامی بیبەری شیرین', 'Crispy bite-sized chicken pieces seasoned with a blend of bold spices, tossed in a sweet chili glaze and finished with a sprinkle of toasted sesame seeds', 'قطع دجاج مقرمشة بحجم لقمة متبلة بمزيج من التوابل، مغطاة بصوص الفلفل الحار الحلو ومزينة برشة من بذور السمسم المحمصة', 'پارچەی مریشکی بچووک و خر تێکەڵکراو بە بەهارات و بە سۆسی بیبەری شیرین  و کونجی برژاو.', 7000, 'https://r2.mynu.site/images/67c05717d8908969203b54ba/items/hd/133905902.jpeg', '{}', true);
insert into public.menu_items (category_id, name_en, name_ar, name_ku, ing_en, ing_ar, ing_ku, price, photo_url, tags, is_available) values ('tartine', 'Creamy Alfredo Chicken Tartine', 'تارتين الدجاج بكريمة ألفريدو', 'تارتینی مریشکی کرێمی ئەلفرێدۆ', 'Salted pancake topped with chicken, mushrooms, mozzarella, parmesan & savory cooking cream.', ' مریشک، قارچک، مۆزارێلا، پارمیسان، و کرێمی چێشتلێنانی بەتام لەسەر پانکەیکێکی نەرم', 'فطيرة مملحة مغطاة بالدجاج والفطر وموزريلا وجبنة بارميزان وكريمة الطهي اللذيذة.
