insert into public.menu_items (category_id, name_en, name_ar, name_ku, ing_en, ing_ar, ing_ku, price, photo_url, tags, is_available) values ('tartine', 'Benedict Tartine', 'بيض بندكت', 'هێلکەی بێنادیکت', 'A soft pancake topped with poached egg.', 'فطيرة بانكيك مملحة مغطاة ببيضة مسلوقة', 'هێلکەی کوڵاو لەسەر پانکەیکێکی نەرم', 8000, 'https://r2.mynu.site/images/67c05717d8908969203b54ba/items/hd/977950588.jpeg', '{}', true);
insert into public.menu_items (category_id, name_en, name_ar, name_ku, ing_en, ing_ar, ing_ku, price, photo_url, tags, is_available) values ('tartine', 'Egg Pomodoro Tartine', 'بيض البومودورو ', '‌هێلکەی پۆمۆدۆرۆ', 'Soft pancake topped with a poached egg and house Pomodoro sauce.', 'فطيرة طرية مغطاة ببيضة مسلوقة وصوص بومودورو', 'پانکەیکێکی نەرم لەگەڵ هێلکەی کوڵاو و سۆسی پۆمۆدۆرۆ.', 6500, 'https://r2.mynu.site/images/67c05717d8908969203b54ba/items/hd/236516994.jpeg', '{}', true);
insert into public.menu_items (category_id, name_en, name_ar, name_ku, ing_en, ing_ar, ing_ku, price, photo_url, tags, is_available) values ('roll', 'Turkey & Cheese Roll', 'لفائف الديك الرومي والجبن', 'ڕۆڵی گۆشتی قەل و پەنیر', 'Soft crepe wrapped around slices of smoked turkey and creamy cheese.', 'كريب ناعم ملفوف حول شرائح من الديك الرومي المدخن وجبنة كريمية.', 'گۆشتی قەلی دوکەڵکراو و پەنیری کرێمی لەناو کریپی نەرم', 10500, 'https://r2.mynu.site/images/67c05717d8908969203b54ba/items/hd/453008946.jpeg', '{}', true);
insert into public.menu_items (category_id, name_en, name_ar, name_ku, ing_en, ing_ar, ing_ku, price, photo_url, tags, is_available) values ('roll', 'Chicken Avocado Roll', 'لفائف الدجاج بالأفوكادو', ' ڕۆڵی مریشک و ئەڤۆکادۆ', 'Soft crepe wrapped around avocado, chicken, crisp garden greens, and honey mustard.', 'كريب ناعم ملفوف حول الأفوكادو، الدجاج، والخضروات الطازجة، وصوص الخردل والعسل.', ' ئەڤۆکادۆ، مریشک، سەوزەی تازە، و سۆسی هانی ماستارد لەناو کریپی نەرم', 12500, 'https://r2.mynu.site/images/67c05717d8908969203b54ba/items/hd/810547231.jpeg', '{}', true);
insert into public.menu_items (category_id, name_en, name_ar, name_ku, ing_en, ing_ar, ing_ku, price, photo_url, tags, is_available) values ('roll', 'Avocado Roll', 'لفائف الأفوكادو', 'ڕۆڵی ئەڤۆکادۆ', 'Soft crepe wrapped around scrambled egg, avocado, crisp garden greens, and guacamole.', 'كريب ناعم ملفوف حول البيض المخفوق، الأفوكادو، الخضروات الطازجة، و صوص جواكامولي.', ' هێلکەی تێکەڵکراو، ئەڤۆکادۆ، سەوزەی تازە، و سۆسی گواکامۆل لەناو کریپی نەرم ', 11500, 'https://r2.mynu.site/images/67c05717d8908969203b54ba/items/hd/693162260.jpeg', '{}', true);
insert into public.menu_items (category_id, name_en, name_ar, name_ku, ing_en, ing_ar, ing_ku, price, photo_url, tags, is_available) values ('roll', 'Mushroom Roll', 'لفائف الفطر', 'ڕۆڵی قارچک', 'Soft crepe wrapped around scrambled egg, Mushroom, crisp garden greens.', 'كريب ناعم ملفوف حول البيض المخفوق، فطر، الخضروات الطازجة.', ' هێلکەی تێکەڵکراو، قارچک، سەوزەی تازە لەناو کریپی نەرم ', 9000, 'https://r2.mynu.site/images/67c05717d8908969203b54ba/items/hd/712362653.jpeg', '{}', true);
insert into public.menu_items (category_id, name_en, name_ar, name_ku, ing_en, ing_ar, ing_ku, price, photo_url, tags, is_available) values ('pizza', 'Alfredo Pizza', 'بيتزا ألفريدو', 'Alfredo Pizza', 'Creamy white sauce, mozzarella & Parmesan, fresh mushrooms, and tender chicken on a golden pizza crust.', 'صلصة بيضاء كريمية، جبن موزاريلا وبارميزان، فطر طازج، ودجاج طري على عجينة بيتزا ذهبية اللون.', null, 13500, 'https://r2.mynu.site/images/67c05717d8908969203b54ba/items/hd/821692570.jpeg', '{}', true);
insert into public.menu_items (category_id, name_en, name_ar, name_ku, ing_en, ing_ar, ing_ku, price, photo_url, tags, is_available) values ('pizza', 'Margherita pizza', 'بيتزا مارغريتا', 'Margherita pizza', 'A timeless favorite with tomato sauce, creamy mozzarella, basil, and a touch of Parmesan', 'طبق كلاسيكي محبوب مع صلصة الطماطم، جبن موزاريلا كريمي، ريحان، ولمسة من جبن البارميزان.', null, 9000, 'https://r2.mynu.site/images/67c05717d8908969203b54ba/items/hd/188703832.jpeg', '{}', true);
insert into public.menu_items (category_id, name_en, name_ar, name_ku, ing_en, ing_ar, ing_ku, price, photo_url, tags, is_available) values ('pizza', 'Veggie pizza', 'بيتزا الخضار', 'Veggie pizza', 'Pizza dough topped with classic pizza sauce, mozzarella, fresh mushrooms, sweet corn, green peppers, black olives, and juicy cherry tomatoes — a colorful bite of garden goodness! ', 'عجينة بيتزا مغطاة بصلصة البيتزا الكلاسيكية، جبن موزاريلا، فطر طازج، ذرة حلوة، فلفل أخضر، زيتون أسود، وطماطم كرزية عصيرية — قضمة مليئة بألوان وروائح حديقة الخضار!', null, 12000, 'https://r2.mynu.site/images/67c05717d8908969203b54ba/items/hd/197258542.jpeg', '{}', true);
