-- One-time MYNU menu seed (Tea Leaves) — run once in Supabase SQL Editor.
-- Replaces all categories and menu items with data from voyager.mynu.app.
-- After running: NOTIFY pgrst, 'reload schema'; (optional if schema unchanged)
-- Future menu edits: use /admin only — do not re-run this migration.

-- Allow items without photos (MYNU has none for some drinks/hookah items).
alter table public.menu_items alter column photo_url drop not null;

delete from public.menu_items;
delete from public.categories;


